  ('lalibela-ethiopia', '05A', 'Lalibela', 'Ethiopia', 'Eleven churches carved from living rock', 'live', 'verified', 'kyoto', 'Horn & Highlands', '{"culture","deepdive","pilgrimage"}', '{}', '{"essential","comfort"}', null, null, '{"key_facts":null,"safety":{"posture":"no-booking","booking_hold":true,"notes":"FCDO advises against all travel to Amhara region.","source":"UK Foreign, Commonwealth & Development Office — Ethiopia travel advice","verified":"2026-05-29","emergency":"991 police · 907 ambulance (Red Cross) · 911 general","malaria":"Active outbreak across all 14 regions; transmission below ~2,500 m. Lalibela sits at ~2,500 m; lowland transit legs carry risk and chemoprophylaxis is advised.","yellow_fever":"Proof required if arriving from or transiting more than 12 hours in a yellow-fever risk country; not required direct from the US. CDC recommends the vaccine for travellers 9 months and over.","activity_note":"Steep church steps, dark interconnecting tunnels and uneven rock. Mild altitude at ~2,500 m; the Asheton Maryam monastery hike rises above 3,000 m.","fcdo":{"posture":"AREA-RESTRICTED","quotes":[],"url":"https://www.gov.uk/foreign-travel-advice/ethiopia","read":"2026-09-01T16:20:18Z","page_updated":"2026-05-29T11:35:25+01:00","source_country":"ethiopia","quotes_note":"not extracted by the join — a restricted-area clause is quoted by a human, never composed"},"zone":"The Amhara Region","fcdo_zones":[{"name":"The Tigray Region","lvl":4,"posture":"all","note":"FCDO advises against all travel. Civilian flights to and from Tigray have been suspended since 29 January 2026."},{"name":"The Amhara Region","lvl":4,"posture":"all","note":"FCDO advises against all travel to all of Amhara regional state."},{"name":"The Gambela Region","lvl":4,"posture":"all","note":"FCDO advises against all travel."},{"name":"Within 20km of the border with Sudan","lvl":4,"posture":"all"},{"name":"Within 10km of the border with South Sudan","lvl":4,"posture":"all"},{"name":"Within 10km of the border with Eritrea","lvl":4,"posture":"all","note":"Including the parts of Afar region within 10km of that border."},{"name":"Within 10km of the border with Kenya","lvl":4,"posture":"all","except":["principal roads and towns"]},{"name":"Somali region border areas","lvl":4,"posture":"all","except":["the border town and crossing at Wajale","the principal road between Jijiga and Wajale"],"note":"Within 100km of the Somalia and Kenya borders in Somali region, and within 30km of the Somalia border in Fafan zone."},{"name":"Named areas of Oromia Region","lvl":4,"posture":"all","note":"North of (not including) the A4 in West Shewa; south and west of the A3 in North Shewa including the A3 itself there; West, East, Kellem and Horo Gudru Wollega zones including the main Addis Ababa to Gambela road."},{"name":"In Benishangul-Gumuz: within 20km of the Sudan border, the Metekel zone and the Maokomo special zone","lvl":4,"posture":"all"},{"name":"In the Central, Southern, Sidama and South West regions (formerly SNNPR): within 10km of the borders with South Sudan and Kenya","lvl":4,"posture":"all","note":"Including the shores of Lake Turkana. The FCDO restricts these border strips, not the whole regions."},{"name":"Areas between 10 and 15km from the border with Eritrea","lvl":3,"posture":"all-but-essential"},{"name":"East Shewa and further named areas of Oromia","lvl":3,"posture":"all-but-essential","except":["the Addis Ababa to Adama Expressway","10km either side of the expressway between Addis Ababa and Bishoftu","the A7 from the expressway junction down to Hawassa","the Hawassa to Mega road (through West Guji and Guji)","the Finfine special zone section of the A4"],"note":"All of East Shewa zone, the A4 between Addis Ababa and Cheliya, the remainder of North Shewa, and West Guji and Guji zones — each with the road exceptions listed."},{"name":"In the Somali Region: the Siti, Nogob, Jarar, Shabelle, Korahe and Dollo zones, and areas of Liben and Afder more than 100km from the Somalia and Kenya borders","lvl":3,"posture":"all-but-essential"},{"name":"The rest of Benishangul-Gumuz Region","lvl":3,"posture":"all-but-essential"}],"zone_record":{"name":"The Amhara Region","lvl":4,"posture":"all","note":"FCDO advises against all travel to all of Amhara regional state."},"zone_record_basis":"exact name match against src/data/safety.json @ ccf2a1c9aecf"},"timing":null,"jewels":[{"name":"Bete Giyorgis, the Church of St George","tier":"essential","si":"culture","blurb":"A perfectly symmetrical Greek-cross monolith hewn about 12 m down into the rock, the best-preserved of the eleven.","source":"https://en.wikipedia.org/wiki/Church_of_Saint_George,_Lalibela","wells":[],"wells_basis":"text supports no Well — needs a human read","si_all":["culture"],"shelf_fit":{"culture":"primary","deepdive":"destination","pilgrimage":"destination"},"commission_lane":[],"commission_embedded":false,"commission_basis":"unparsed"},{"name":"The two interconnected church clusters","tier":"essential","si":"culture","blurb":"Eleven medieval monolithic churches carved from solid rock in the late 12th to early 13th century, UNESCO-listed in 1978.","source":"https://whc.unesco.org/en/list/18/","wells":[],"wells_basis":"text supports no Well — needs a human read","si_all":["culture"],"shelf_fit":{"culture":"primary","deepdive":"destination","pilgrimage":"destination"},"commission_lane":[],"commission_embedded":false,"commission_basis":"unparsed"},{"name":"Genna at Lalibela","tier":"essential","si":"pilgrimage","blurb":"Ethiopian Christmas on 7 January, when the rock-hewn churches fill with the chant of a living faith.","source":"https://www.brilliant-ethiopia.com/christmas-in-lalibela","wells":[],"wells_basis":"text supports no Well — needs a human read","si_all":["pilgrimage"],"shelf_fit":{"culture":"destination","deepdive":"destination","pilgrimage":"primary"},"commission_lane":[],"commission_embedded":false,"commission_basis":"unparsed"},{"name":"The Asheton Maryam monastery hike","tier":"comfort","si":"deepdive","blurb":"A climb above 3,000 m to a monastery in the cliffs over the town.","source":"https://www.brilliant-ethiopia.com/asheton-maryam-monastery-lalibela","wells":["activities"],"wells_basis":"derived from name/blurb/hook","si_all":["deepdive","pilgrimage"],"shelf_fit":{"culture":"destination","deepdive":"primary","pilgrimage":"evidenced"},"commission_lane":[],"commission_embedded":false,"commission_basis":"unparsed"}],"faq":[{"q":"What is Lalibela?","a":"Eleven medieval monolithic churches carved straight down into solid volcanic rock in the late 12th to early 13th century, UNESCO-listed in 1978 and still a living Orthodox worship site. It was conceived as a New Jerusalem so Ethiopian Christians could make pilgrimage at home after Muslim conquests cut off the Holy Land.","source":"https://whc.unesco.org/en/list/18/"},{"q":"When do the churches fill with pilgrims?","a":"At Genna, Ethiopian Christmas, on 7 January. The dry season runs October to March at roughly 15 to 25C.","source":"https://www.brilliant-ethiopia.com/christmas-in-lalibela"},{"q":"What are the emergency numbers in Ethiopia?","a":"991 for police, 907 for the Red Cross ambulance, 911 general. An older note circulating as 939 is the fire service, not an ambulance.","source":"https://addisababa.embassy.qa/en/ethiopia/important-numbers"}],"seo":{"meta_title":"Lalibela, Ethiopia — the rock-hewn churches | TravelWell.World","meta_description":"Eleven medieval monolithic churches carved from living rock, UNESCO-listed in 1978, still a living Orthodox pilgrimage site. Why we do not currently book Ethiopia''s Amhara region.","slug":"lalibela-ethiopia","jsonld_type":"TouristDestination","content_freshness":"2026-08-16","primary_keyword":"Lalibela rock-hewn churches","attribution":{"author":{"type":"Organization","name":"TravelWell.World"},"publisher":{"type":"Organization","name":"TravelWell.World LLC"},"reviewed_by":{"type":"Organization","name":"TravelWell.World"},"digital_source_type":"CompositeWithTrainedAlgorithmicMediaDigitalSource","digital_source_vocab":"https://schema.org/IPTCDigitalSourceEnumeration","last_verified":"2026-08-16","last_verified_basis":"source_verified","verified_against":[{"name":"UK Foreign, Commonwealth & Development Office","url":"https://www.gov.uk/foreign-travel-advice/ethiopia","read":"2026-08-20T14:54:07Z","source_updated":"2026-05-29T11:35:25+01:00"}]}},"booking":{"advisory_authority":"FCDO"},"si_checklist_25":null,"sis_present":["culture","deepdive","pilgrimage"],"ultra":null,"source_verified":"2026-08-16","hero":{"query":"Lalibela, Ethiopia"},"geo":{"lat":12.0361,"lng":39.0457},"geo_source":"https://nominatim.openstreetmap.org/search?q=Lalibela,+Ethiopia — OpenStreetMap Nominatim, place/town, North Wollo, Amhara, 2026","geo_accessed":"2026-08-18","orbit":[],"orbit_country":[]}'::jsonb, 11),
  ('murchison-falls-uganda', '05A', 'Murchison Falls National Park', 'Uganda', 'The world''s most powerful waterfall, four of the Big', 'live', 'verified', 'safariJeep', 'Uganda — Murchison Falls / Nile', '{"safari","adventure","ultra","deepdive"}', '{}', '{"essential","comfort","premier","ultra"}', null, null, '{"key_facts":["CONTENT-ONLY, no Book path, no waiver. DYNAMIC - re-verify each cycle, flip to live when it clears. Redirect safari demand to Kenya/Tanzania/Akagera","Uganda''s largest park (~3,840 km2), bisected by the Victoria Nile which funnels through a 7-m gorge and plunges 43 m - often called the world''s most powerful waterfall","The Big Four (lion, elephant, buffalo, leopard - NO rhino in-park; rhino at the separate Ziwa Rhino Sanctuary en route) + endangered Nubian giraffe, across 76+ mammals; 450+ birds incl. the shoebill","The Nile boat safari to the base of the falls ($30) - hippos, giant crocs, elephants, buffalo; delta shoebill cruise; the top-of-falls hike (all latent while held)","Park fee $40 (24h); yellow fever MANDATORY for entry (all >=1yr, checked at Entebbe); eVisa (no visa-on-arrival); ~300 km / 4h NW of Kampala; malaria in all regions (prophylaxis) - all latent while held","Live twins = Kenya (Maasai Mara/Amboseli), Tanzania (Serengeti), akagera-np-rwanda (Rwanda Big Five). Anchors the Uganda cluster with bwindi/queen-elizabeth/kibale"],"safety":{"emergency":"999 / 112","hospital":"Remote - AMREF Flying Doctors (~$40 pp/30d) + travel-medical insurance; nearest referral Masindi/Gulu/Kampala (all latent while held)","malaria":"present in all regions - prophylaxis (latent while held)","yellow_fever":"MANDATORY for entry (all >=1yr, checked at Entebbe, >=10 days before)","ebola":"Sudan virus outbreak - PHEIC declared 2026-05-17 - the dominant, disqualifying hazard","activity_note":"HEALTH-SPINE DOMINANT: Ebola outbreak is the hazard. FCDO BASIS (gov.uk/foreign-travel-advice/uganda, read 2026-08-20): health screening on arrival and departure; Ugandan border with the DRC closed from 27 May per the National Task Force; the UK Returning Workers Scheme activated due to the outbreak. NOTE THE FCDO ADVISES AGAINST NO TRAVEL TO UGANDA - posture 1 - so any book-suppression here is OUR health judgement, not an advisory one, and is DAVID''S CALL - CONTENT-ONLY, Book suppressed, no waiver, redirect to Kenya/Tanzania/Akagera. DYNAMIC - re-verify each cycle. Safari/boat/falls + malaria hazards secondary and moot while held. When reopened: top-of-falls behind railings/guides, keep back from hippos/crocs on the Nile boat, standard game-drive rules","booking_hold":false,"fcdo":{"posture":"1","quotes":[],"url":"https://www.gov.uk/foreign-travel-advice/uganda","read":"2026-09-04T12:02:58Z","page_updated":"2026-09-02T16:45:31+01:00","source_country":"uganda","quotes_note":"not extracted by the join — a restricted-area clause is quoted by a human, never composed","posture_basis":"alert_status empty; quoted sentences name another country","posture_corrected":"2026-08-23 - was AREA-RESTRICTED, derived from prose about a neighbour"},"posture":"book-freely"},"timing":{"latent_peak":"Dec-Feb + Jun-Sep (drier - game near the Nile, firmer tracks) - IF cleared","latent_green":"Mar-May + Oct-Nov (rains, lush/birdy, softer rates; falls fullest after rain)","latent_booking_lead":"lodges 2-4 mo peak - NOT applicable while held","reverify_trigger":"check Uganda''s advisory EVERY publish cycle - DYNAMIC health advisory; flip to live the moment it drops below","redirect":"live safari demand -> Kenya (Maasai Mara/Amboseli) / Tanzania (Serengeti) / akagera-np-rwanda (Rwanda Big Five)"},"jewels":[{"name":"Big-Four game on the Nile plains","status":"held","tier":"premier","price_band":"HELD - no book path","timing":"HELD; latent Dec-Feb + Jun-Sep","draw_rank":null,"hook":"four of the Big Five — lion, elephant, buffalo, leopard — plus herds of the endangered Nubian giraffe across Uganda''s largest park","si":"safari","blurb":"four of the Big Five — lion, elephant, buffalo, leopard — plus herds of the endangered Nubian giraffe across Uganda''s largest park","when":"HELD; latent Dec-Feb + Jun-Sep","commission":"none (advisory hold)","wells":[],"wells_basis":"text supports no Well — needs a human read","si_all":["safari"],"shelf_fit":{"adventure":"destination","deepdive":"destination","safari":"primary","ultra":"destination"},"commission_lane":["none"],"commission_embedded":false,"commission_basis":"lane"},{"name":"The Nile boat safari to the base of the falls","status":"held","tier":"essential","price_band":"HELD (Nile boat $30 latent)","timing":"HELD","draw_rank":null,"hook":"a boat cruise up the Victoria Nile to the foot of the thundering falls","si":"adventure","blurb":"a boat cruise up the Victoria Nile to the foot of the thundering falls","when":"HELD","commission":"none (advisory hold)","wells":["move","activities"],"wells_basis":"derived from name/blurb/hook","si_all":["adventure","safari"],"shelf_fit":{"adventure":"primary","deepdive":"destination","safari":"evidenced","ultra":"destination"},"commission_lane":["none"],"commission_embedded":false,"commission_basis":"lane"},{"name":"The top-of-the-falls hike","status":"held","tier":"essential","price_band":"HELD - no book path","timing":"HELD","draw_rank":null,"hook":"a short, steep walk to the lip where the entire Nile is squeezed through a 7-m slot and hurled 43 m","si":"adventure","blurb":"a short, steep walk to the lip where the entire Nile is squeezed through a 7-m slot and hurled 43 m","when":"HELD","commission":"none (advisory hold)","wells":["activities"],"wells_basis":"derived from name/blurb/hook","si_all":["adventure"],"shelf_fit":{"adventure":"primary","deepdive":"destination","safari":"destination","ultra":"destination"},"commission_lane":["none"],"commission_embedded":false,"commission_basis":"lane"},{"name":"A shoebill + 450-bird delta","status":"held","tier":"premier","price_band":"HELD - no book path","timing":"HELD","draw_rank":null,"hook":"the Nile delta is one of the best places on Earth to see the prehistoric, statue-still shoebill","si":"deepdive","blurb":"the Nile delta is one of the best places on Earth to see the prehistoric, statue-still shoebill","when":"HELD","commission":"none (advisory hold)","wells":[],"wells_basis":"text supports no Well — needs a human read","si_all":["deepdive"],"shelf_fit":{"adventure":"destination","deepdive":"primary","safari":"destination","ultra":"destination"},"commission_lane":["none"],"commission_embedded":false,"commission_basis":"lane"},{"name":"A Nile safari-lodge honeymoon (held)","status":"held","tier":"comfort","price_band":"HELD - no book path","timing":"HELD","draw_rank":null,"hook":"Nile Safari Lodge and Baker''s Lodge on the river''s edge, Paraa and Chobe overlooking the water","si":"ultra","blurb":"Nile Safari Lodge and Baker''s Lodge on the river''s edge, Paraa and Chobe overlooking the water","when":"HELD","commission":"none (advisory hold)","wells":["stay","activities"],"wells_basis":"derived from name/blurb/hook","si_all":["safari","ultra"],"shelf_fit":{"adventure":"destination","deepdive":"destination","safari":"evidenced","ultra":"primary"},"commission_lane":["none"],"commission_embedded":false,"commission_basis":"lane"}],"faq":[{"q":"Where can I go on safari instead, right now?","a":"Kenya (Maasai Mara / Amboseli,, bookable) or Tanzania (Serengeti / Ngorongoro,, bookable) for the classic Big-game plains - or Akagera, Rwanda (US, a Big-Five comeback ~2h from Kigali) for the nearest live savanna. We route all Uganda safari demand there.","source":"travelweekly.com","si_tag":"safety"},{"q":"Will this clear - should I wait for Murchison?","a":"Possibly - this is a health-driven, dynamic advisory (an outbreak, not conflict), so it can be lifted when the outbreak is contained. For a firm 2026 safari, book Kenya, Tanzania or Akagera now.","source":"travelweekly.com","si_tag":"safety"},{"q":"What would Murchison offer when it reopens?","a":"Uganda''s largest park - the world''s most powerful waterfall (the Nile through a 7-m gorge), four of the Big Five plus Nubian giraffe, the Nile boat safari to the falls'' base, delta shoebill cruises and a top-of-falls hike. All held until the advisory lifts.","source":"mustseespots.com","si_tag":"safari"},{"q":"Is there rhino - is it a Big Five park?","a":"Four of the five: lion, elephant, buffalo and leopard live in the park - no rhino in Murchison itself. Rhino are seen at the separate Ziwa Rhino Sanctuary on the drive up from Kampala (also held while Uganda is).","source":"worldblossomsafari.com","si_tag":"safari"},{"q":"What are the non-Ebola health requirements for Uganda?","a":"Yellow fever is mandatory for entry (all travelers >=1 yr, checked at Entebbe, vaccinate >=10 days before); malaria prophylaxis is essential (all regions); carry AMREF Flying Doctors + insurance.","source":"cdc.gov","si_tag":"safety"}],"seo":{"meta_description":"What it is, why it''s held, and where to safari instead (Kenya, Tanzania, Rwanda''s Akagera).","slug":"murchison-falls-uganda","primary_keyword":"Murchison Falls National Park safari","long_tail":["Murchison Falls Nile boat cruise","world''s most powerful waterfall","Murchison Big Four","shoebill Murchison delta","is Uganda safe Ebola","Murchison vs Serengeti"],"search_language":"en","local_keywords":["Murchison","Kabalega Falls","Victoria Nile","Paraa","shoebill","Nubian giraffe"],"hreflang":["en"],"jsonld_type":"TouristDestination","content_freshness":"2026-08-01","attribution":{"author":{"type":"Organization","name":"TravelWell.World"},"publisher":{"type":"Organization","name":"TravelWell.World LLC"},"reviewed_by":{"type":"Organization","name":"TravelWell.World"},"digital_source_type":"CompositeWithTrainedAlgorithmicMediaDigitalSource","digital_source_vocab":"https://schema.org/IPTCDigitalSourceEnumeration","last_verified":"2026-08-01","last_verified_basis":"source_verified","verified_against":[{"name":"UK Foreign, Commonwealth & Development Office","url":"https://www.gov.uk/foreign-travel-advice/uganda","read":"2026-08-20T14:48:47Z","source_updated":"2026-07-27T15:00:28+01:00"}]}},"booking":{"codes":["do-not-travel","ebola-sudan-virus-pheic","health-outbreak"],"book_suppressed":true,"waiver":false,"dynamic":true,"note":"CONTENT-ONLY, Book button suppressed, no waiver. DYNAMIC health advisory - re-verify EVERY publish cycle; Redirect live safari demand to Kenya (Maasai Mara/Amboseli), Tanzania (Serengeti), akagera-np-rwanda (Rwanda Big Five).","advisory_authority":"FCDO"},"si_checklist_25":{"run_date":"2026-08-01","hits":6,"misses":16,"disregarded":3,"note":"Canonical 25-SI list; safari = Big-Four game (primary when live), globaladv = Nile boat safari + top-of-falls hike; sports limited to participant; spectator/prosports/compsports disregarded"},"sis_present":[{"si":"safari","name":"safari","status":"held","note":"Big-Four game (lion/elephant/buffalo/leopard) + Nubian giraffe"},{"si":"globaladv","name":"adventure","status":"held","note":"Nile boat safari to the base of the falls + top-of-falls hike"},{"si":"ultra","name":"ultra","status":"held"},{"si":"deepdive","name":"deepdive","status":"held","note":"shoebill / 450+ birds"}],"ultra":[{"name":"Nile Safari Lodge / Baker''s Lodge (HELD)","why_ultra":"the park''s apex stays - barefoot-luxury bandas on the Nile''s edge; documented for the day the hold lifts, sold by no one today","earning":"none while held","virtuoso_value_add":false,"tier":"ultra","status":"HELD"},{"name":"A private falls + Nile + delta + Ziwa-rhino week (HELD)","why_ultra":"the top-of-falls hike + the boat to the base + the shoebill delta + a Ziwa rhino add-on en route, privately guided - latent","earning":"none while held","virtuoso_value_add":false,"tier":"ultra","status":"HELD"}],"source_verified":"2026-08-01","hero":{"query":"Murchison Falls National Park, Uganda"},"geo":{"lat":2.2,"lng":31.8},"orbit":[],"orbit_country":["bwindi-impenetrable-uganda","kibale-forest-uganda","queen-elizabeth-np-uganda"]}'::jsonb, 12),
  ('ngorongoro-crater-tanzania', '05A', 'Ngorongoro Crater', 'Tanzania', 'The world''s largest caldera', 'live', 'verified', 'safariJeep', 'Tanzania — Northern Safari Circuit / Ngorongoro', '{"safari","ultra","romance","deepdive","culture","adventure"}', '{}', '{"essential","comfort","premier","luxury","ultra"}', null, 'anchor', '{"key_facts":["World''s largest intact volcanic caldera (UNESCO 1979) - 600-m walls, 2-3 M years old; ~25,000 large mammals at Africa''s highest predator density","The best Big-Five-in-one-day in Africa (lion, elephant, buffalo, leopard, resident black rhino <30); ideal first safari","Olduvai Gorge (cradle of mankind - Homo habilis, ~3.6 M-year fossils) within the Conservation Area; Maasai coexist and graze the highlands","Game dense YEAR-ROUND (animals stay in the crater); dry Jun-Oct clearest, Jan-Feb greener/quieter, Apr-May cheapest; usually 1 crater day in a Northern-Circuit loop","LGBTQ+ flagged); NCAA fees pass-through ($70.80/adult + $295/vehicle descent + VAT); sold via safari DMCs IATAN-not-CLIA","TZS but USD is the safari currency; eVisa; malaria prophylaxis advised (lower at rim); Seneto descent ~600m steep; AMREF Flying Doctors for evac"],"safety":{"emergency":"112 / 999 (unreliable outside cities; no reliable govt ambulance - rely on camp/operator radio + AMREF Flying Doctors)","hospital":"Remote - AMREF Flying Doctors (~$40 pp/30d) + travel-medical insurance; nearest referral Arusha","malaria":"prophylaxis advised - lower at the 2,200-2,300m rim but the floor/surrounds are malarial; DEET at dusk","yellow_fever":"not required from a non-risk country; mandatory if transiting >12h a risk country (e.g. Kenya)","activity_note":"LGBTQ+ targeting flagged). Dangerous game at close range on the floor - stay in the vehicle, follow the guide. Seneto descent ~600m steep/narrow (dry conditions, 4x4). Rim altitude ~2,200-2,300m mild effects. Remote - carry AMREF evac + insurance","fcdo":{"posture":"AREA-RESTRICTED","quotes":[],"url":"https://www.gov.uk/foreign-travel-advice/tanzania","read":"2026-09-01T16:20:26Z","page_updated":"2026-05-19T15:47:49+01:00","source_country":"tanzania","quotes_note":"not extracted by the join — a restricted-area clause is quoted by a human, never composed"}},"timing":{"peak":"Jun-Oct (dry, clearest viewing) + Dec-Feb (holiday + Serengeti-calving combo)","shoulder":"Nov + Mar (quieter, softer rates, good game)","green":"Apr-May (long rains - green, quietest, cheapest)","booking_lead":"rim lodges + Northern-Circuit 6-12 mo for Jun-Oct + Dec-Feb (crater-rim luxury sells out); shoulder 3-6 mo; green 1-3 mo","off_season_specials":"Apr-May green-season value; combine Serengeti calving (Jan-Feb) or Tarangire/Manyara","event_peaks":"Jun-Oct high season + Christmas/NY + Easter; daily-vehicle-cap makes peak floor access tight","fire_date":"Jun-Oct loops 9-12 mo out; Jan-Feb calving+crater combos by prior Apr-Jun; green-season value by prior Nov-Dec"},"jewels":[{"name":"The Big-Five crater-floor game drive","status":"live","tier":"comfort","price_band":"~$700-2,000/pp/day","timing":"year-round; dry Jun-Oct clearest","draw_rank":1,"hook":"the most reliable Big-Five day in Africa — lion, elephant, buffalo, leopard and rhino on one grassy floor at the continent''s highest predator density","si":"safari","blurb":"the most reliable Big-Five day in Africa — lion, elephant, buffalo, leopard and rhino on one grassy floor at the continent''s highest predator density","when":"year-round; dry Jun-Oct clearest","commission":"safari DMC 10-15%","wells":["move"],"wells_basis":"derived from name/blurb/hook","si_all":["safari"],"shelf_fit":{"adventure":"destination","culture":"destination","deepdive":"destination","romance":"destination","safari":"primary","ultra":"destination"},"commission_pct_low":10,"commission_pct_high":15,"commission_lane":["DMC"],"commission_embedded":false,"commission_basis":"band+lane"},{"name":"Black-rhino tracking","status":"live","tier":"premier","price_band":"within the crater day","timing":"Jun-Oct  + Dec-Feb","draw_rank":2,"when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","hook":"a resident population of endangered black rhino on the floor — one of East Africa''s most reliable rhino sightings, guide-radio-coordinated","si":"safari","blurb":"a resident population of endangered black rhino on the floor — one of East Africa''s most reliable rhino sightings, guide-radio-coordinated","when":"Jun-Oct  + Dec-Feb","commission":"safari DMC 10-15%","wells":["activities"],"wells_basis":"derived from name/blurb/hook","si_all":["safari"],"shelf_fit":{"adventure":"destination","culture":"destination","deepdive":"destination","romance":"destination","safari":"primary","ultra":"destination"},"commission_pct_low":10,"commission_pct_high":15,"commission_lane":["DMC"],"commission_embedded":false,"commission_basis":"band+lane"},{"name":"Olduvai Gorge - the cradle of mankind","status":"future","tier":"essential","price_band":"~$30-60/pp","timing":"Jun-Oct  + Dec-Feb","draw_rank":1,"when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","hook":"within the Conservation Area — the human-origins site of Homo habilis and fossils to ~3.6 M years, with a museum","si":"deepdive","blurb":"within the Conservation Area — the human-origins site of Homo habilis and fossils to ~3.6 M years, with a museum","when":"Jun-Oct  + Dec-Feb","commission":"DMC/venue","wells":["activities"],"wells_basis":"derived from name/blurb/hook","si_all":["culture","deepdive"],"shelf_fit":{"adventure":"destination","culture":"evidenced","deepdive":"primary","romance":"destination","safari":"destination","ultra":"destination"},"commission_lane":["DMC","venue"],"commission_embedded":false,"commission_basis":"lane"},{"name":"A Maasai boma visit (highlands)","status":"future","tier":"essential","price_band":"~$20-40/pp","timing":"Jun-Oct  + Dec-Feb","draw_rank":1,"when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","hook":"the pastoralist Maasai who share the Conservation Area — a boma visit, dance and beadwork with a fair-trade operator","si":"culture","blurb":"the pastoralist Maasai who share the Conservation Area — a boma visit, dance and beadwork with a fair-trade operator","when":"Jun-Oct  + Dec-Feb","commission":"DMC/community","wells":[],"wells_basis":"text supports no Well — needs a human read","si_all":["culture"],"shelf_fit":{"adventure":"destination","culture":"primary","deepdive":"destination","romance":"destination","safari":"destination","ultra":"destination"},"commission_lane":["DMC"],"commission_embedded":false,"commission_basis":"lane"},{"name":"A highland crater walk (Empakaai / Olmoti)","status":"future","tier":"premier","price_band":"~$60-150/pp","timing":"dry season; guided","draw_rank":1,"hook":"beyond the main crater — guided walks to the flamingo-ringed Empakaai crater lake and Olmoti''s waterfall, a rare on-foot angle in the highlands","si":"adventure","blurb":"beyond the main crater — guided walks to the flamingo-ringed Empakaai crater lake and Olmoti''s waterfall, a rare on-foot angle in the highlands","when":"dry season; guided","commission":"DMC/camp","wells":["activities"],"wells_basis":"derived from name/blurb/hook","si_all":["adventure"],"shelf_fit":{"adventure":"primary","culture":"destination","deepdive":"destination","romance":"destination","safari":"destination","ultra":"destination"},"commission_lane":["DMC"],"commission_embedded":false,"commission_basis":"lane"},{"name":"A crater-rim luxury lodge honeymoon","status":"live","tier":"luxury","price_band":"~$1,200-3,500+/night all-in","timing":"standing; peak 6-12 mo","draw_rank":1,"hook":"&Beyond Ngorongoro Crater Lodge and the rim''s grand lodges perch on the caldera edge — fireplaces, butlers and the crater at your feet; honeymoon-grade","si":"ultra","blurb":"&Beyond Ngorongoro Crater Lodge and the rim''s grand lodges perch on the caldera edge — fireplaces, butlers and the crater at your feet; honeymoon-grade","when":"standing; peak 6-12 mo","commission":"consortia/Virtuoso + DMC","wells":["stay"],"wells_basis":"derived from name/blurb/hook","si_all":["romance","ultra"],"shelf_fit":{"adventure":"destination","culture":"destination","deepdive":"destination","romance":"evidenced","safari":"destination","ultra":"primary"},"commission_lane":["DMC","consortia"],"commission_embedded":false,"commission_basis":"lane"},{"name":"Crater-rim romance (&Beyond / rim lodges)","status":"live","tier":"luxury","price_band":"on application","timing":"Jun-Oct  + Dec-Feb","draw_rank":1,"when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"romance","when":"Jun-Oct  + Dec-Feb","commission":"consortia/host","wells":["stay"],"wells_basis":"derived from name/blurb/hook","si_all":["romance"],"shelf_fit":{"adventure":"destination","culture":"destination","deepdive":"destination","romance":"primary","safari":"destination","ultra":"destination"},"commission_lane":["consortia"],"commission_embedded":false,"commission_basis":"lane"}],"faq":[{"q":"What''s the real risk to plan for at Ngorongoro?","a":"Dangerous game and the descent, not crime. Big game is at close range on the crater floor - stay in the vehicle and follow your guide; the one-way Seneto descent drops ~600m on a steep narrow road (best in dry conditions). Carry AMREF Flying Doctors evac + travel-medical insurance for the remoteness.","source":"pangolinphoto.com","si_tag":"safety"},{"q":"Should LGBTQ+ travelers be aware of anything in Tanzania?","a":"Yes, plainly - Tanzanian law criminalizes same-sex relations and the US advisory flags targeting of LGBTQ+ travelers; a real consideration we''ll discuss candidly before booking.","source":"newsweek.com","si_tag":"safety"},{"q":"When is the best time to visit Ngorongoro Crater?","a":"Game is dense year-round (the animals don''t leave the crater), so it''s about crowds: dry Jun-Oct is best-viewing but busiest; Jan-Feb is green, quieter and pairs with the Serengeti calving; Apr-May is cheapest.","source":"asiliaafrica.com","si_tag":"safari"},{"q":"Is Ngorongoro worth it and how does it fit a trip?","a":"Yes - unmatched density and a true Big-Five day in one compact location, ideal for first-time safari-goers. It''s usually one crater day within a Northern-Circuit loop (Serengeti + Tarangire/Manyara).","source":"getsafaritours.com","si_tag":"safari"},{"q":"What does it cost to enter Ngorongoro?","a":"The NCAA fees are significant and pass-through: ~$70.80/adult conservation entry + a $295/vehicle crater-descent fee (plus VAT), bundled into your DMC package; the safari land (lodge + game drive) is where advisor commission sits.","source":"ngorongorocratertanzania.org","si_tag":"safari"}],"seo":{"meta_description":"Plan a Ngorongoro Crater safari - the world''s largest intact caldera (UNESCO 1979): the Big Five in a single day at Africa''s highest predator density, resident black rhino, Olduvai Gorge, Maasai highlands, 2026 NCAA fees, plus the FCDO advisory, timing and evac intel.","slug":"ngorongoro-crater-tanzania","primary_keyword":"Ngorongoro Crater safari","long_tail":["Ngorongoro Crater Big Five","Ngorongoro crater fees 2026","black rhino Ngorongoro","Olduvai Gorge","best time Ngorongoro","is Ngorongoro safe","Ngorongoro vs Serengeti"],"search_language":"sw","local_keywords":["Ngorongoro","Kaldera","Olduvai","faru","simba","Wamasai","Bonde la Olduvai"],"hreflang":["en","sw"],"jsonld_type":"TouristDestination","content_freshness":"2026-07-31","attribution":{"author":{"type":"Organization","name":"TravelWell.World"},"publisher":{"type":"Organization","name":"TravelWell.World LLC"},"reviewed_by":{"type":"Organization","name":"TravelWell.World"},"digital_source_type":"CompositeWithTrainedAlgorithmicMediaDigitalSource","digital_source_vocab":"https://schema.org/IPTCDigitalSourceEnumeration","last_verified":"2026-07-31","last_verified_basis":"source_verified","verified_against":[{"name":"UK Foreign, Commonwealth & Development Office","url":"https://www.gov.uk/foreign-travel-advice/tanzania","read":"2026-08-20T14:54:17Z","source_updated":"2026-05-19T15:47:49+01:00"}]}},"booking":{"codes":["reconsider-travel","terrorism-mtwara","crime","lgbtq-targeting"],"book_suppressed":false,"note":"Ngorongoro is a well-established, beginner-friendly safari with a licensed operator. LGBTQ+ travelers: same-sex relations criminalized + advisory flags targeting - surface plainly. Re-verify each cycle.","advisory_authority":"FCDO"},"si_checklist_25":{"run_date":"2026-07-31","hits":7,"misses":15,"disregarded":3,"note":"Canonical 25-SI list; SAFARI is the launch/demo SI - primary safari not globaladv; Olduvai/human-origins = deepdive; highland crater walks = globaladv; sports limited to participant; spectator/prosports/compsports disregarded"},"sis_present":[{"si":"safari","name":"safari","status":"live"},{"si":"ultra","name":"ultra","status":"live"},{"si":"romance","name":"Romance, Marriages & Honeymoons","status":"live"},{"si":"deepdive","name":"deepdive","status":"future","note":"Olduvai Gorge / human origins"},{"si":"culture","name":"culture","status":"future","note":"Maasai"},{"si":"globaladv","name":"adventure","status":"future","note":"Empakaai/Olmoti highland walks"}],"ultra":[{"name":"&Beyond Ngorongoro Crater Lodge - the rim''s apex stay","why_ultra":"the ''Maasai Versailles'' on the caldera edge - butlered suites and the crater below","earning":"consortia/Virtuoso","virtuoso_value_add":true,"mor":"commissionable-rack","tier":"ultra","price_band":"~$1,800-3,500+/night"},{"name":"A private crater day + Olduvai + Maasai (private guide)","why_ultra":"exclusive-vehicle Big-Five crater day + the cradle-of-mankind gorge + a Maasai boma, privately guided","earning":"DMC/consortia","virtuoso_value_add":false,"mor":"commissionable","tier":"ultra","price_band":"on application"},{"name":"A Northern-Circuit private-guided week (Serengeti + Ngorongoro + Tarangire)","why_ultra":"private guide/vehicle across the marquee parks, luxury camps throughout","earning":"DMC/consortia","virtuoso_value_add":false,"mor":"commissionable","tier":"ultra","price_band":"on application"}],"source_verified":"2026-07-31","hero":{"query":"Ngorongoro Crater, Tanzania"},"geo":{"lat":-3.2,"lng":35.5},"orbit":[],"orbit_country":["lake-manyara-tanzania","nyerere-selous-tanzania","ruaha-tanzania","serengeti-tanzania","tarangire-tanzania"],"reconciles_live_mvp":"ngorongoro-tanzania"}'::jsonb, 13),
  ('nyerere-selous-tanzania', '05A', 'Nyerere National Park (Selous)', 'Tanzania', 'A boat safari down the Rufiji, wild dogs on', 'live', 'verified', 'safariJeep', 'Tanzania — Southern Circuit / Nyerere-Selous', '{"safari","adventure","ultra","romance","deepdive"}', '{}', '{"essential","comfort","premier","luxury","ultra"}', null, 'core', '{"key_facts":["The largest national park in Africa (~30,893 km2 - over twice the Serengeti), created 2019 from the northern part of the UNESCO-listed (1982) Selous Game Reserve, named for founding president Julius Nyerere","The Rufiji River (250+ km) makes Nyerere the finest boat-safari park in Tanzania - the signature experience (hippo, crocodile, birdlife), water-borne game viewing rare in the country","A wild-dog stronghold - one of Africa''s largest remaining African wild-dog populations (the transboundary Selous-Niassa population); the Big Five incl. a remnant black rhino (rarely seen)","Nyerere''s TOURIST sector is the northern Rufiji (near Dar), away from the park''s far-southern reaches; disclose LGBTQ+ targeting; licensed operator","Best Jun-Oct (dry - game on the river); green season Nov-Mar birdy/lush; long rains Apr-May close many camps; ~45-min fly-in from Dar; pair with Ruaha for a southern-circuit week","Sold via Tanzanian safari DMCs + camp consortia 10-20%+ - IATAN/host-gated, CLIA has NO Africa representation; light-aircraft fly-in + TANAPA park/boat fees are pass-through; TZS (~2,633/USD, USD is the safari currency); eVisa; low wet park - malaria prophylaxis essential; AMREF for evac"],"safety":{"emergency":"112 / 999","hospital":"Remote low-lying river wilderness - AMREF Flying Doctors (~$40 pp/30d) + travel-medical insurance; nearest referral Dar es Salaam","malaria":"present and HIGHER than the northern circuit (low-elevation river park) - prophylaxis + DEET essential","yellow_fever":"not required direct from US/Europe; mandatory if transiting >12h through a risk country (e.g. Kenya)","activity_note":"Nyerere''s tourist sector is the northern Rufiji, away from the far-southern reaches; disclose LGBTQ+ targeting - same-sex relations criminalized; travel with a licensed operator, keep to the northern Rufiji sector). Rufiji boat safari: keep back from hippos/crocs, life jacket, licensed crew. Walking safari only with armed ranger. Low wet park - malaria prophylaxis essential; AMREF evac","fcdo":{"posture":"AREA-RESTRICTED","quotes":[],"url":"https://www.gov.uk/foreign-travel-advice/tanzania","read":"2026-09-01T16:20:26Z","page_updated":"2026-05-19T15:47:49+01:00","source_country":"tanzania","quotes_note":"not extracted by the join — a restricted-area clause is quoted by a human, never composed"}},"timing":{"peak":"Jun-Oct (dry) - game concentrates on the Rufiji and its lakes; the premier season; book 4-8 mo ahead (few camps)","shoulder":"Nov + Jan-Mar (green flushes, good birding, softer rates/crowds)","green":"Apr-May (long rains - many camps close; roads soften)","booking_lead":"premium camps 4-8 mo for Jun-Oct (limited beds); green 1-3 mo","off_season_specials":"green-season birding + boat safaris (Rufiji spectacular when full); the southern-circuit combo (Nyerere + Ruaha) as an uncrowded water-based alternative to the north","event_peaks":"Jul-Oct + Christmas/NY; the dry-season river spectacle","fire_date":"Jun-Oct 6-9 mo out (beds scarce); the Nyerere + Ruaha southern-circuit combo by prior Aug-Oct; position as the boat-safari-and-wild-dog star beyond the northern crowds"},"jewels":[{"name":"A wild-dog stronghold + the Big Five","status":"live","tier":"premier","price_band":"camp + park fees","timing":"Jun-Oct peak","draw_rank":1,"hook":"one of Africa''s largest remaining African wild-dog populations hunts these plains, alongside lion, leopard, elephant, buffalo and a remnant black rhino","si":"safari","blurb":"one of Africa''s largest remaining African wild-dog populations hunts these plains, alongside lion, leopard, elephant, buffalo and a remnant black rhino","when":"Jun-Oct peak","commission":"DMC/camp","wells":[],"wells_basis":"text supports no Well — needs a human read","si_all":["safari"],"shelf_fit":{"adventure":"destination","deepdive":"destination","romance":"destination","safari":"primary","ultra":"destination"},"commission_lane":["DMC"],"commission_embedded":false,"commission_basis":"lane"},{"name":"Game drives through the largest park in Africa","status":"live","tier":"premier","price_band":"camp + park fees","timing":"Jun-Oct","draw_rank":2,"when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","hook":"elephant herds, big cats and plains game across an immense, uncrowded wilderness of the Rufiji''s channels and lakes","si":"safari","blurb":"elephant herds, big cats and plains game across an immense, uncrowded wilderness of the Rufiji''s channels and lakes","when":"Jun-Oct","commission":"DMC/camp","wells":[],"wells_basis":"text supports no Well — needs a human read","si_all":["safari"],"shelf_fit":{"adventure":"destination","deepdive":"destination","romance":"destination","safari":"primary","ultra":"destination"},"commission_lane":["DMC"],"commission_embedded":false,"commission_basis":"lane"},{"name":"The Rufiji River boat safari","status":"live","tier":"premier","price_band":"~$50-150/pp","timing":"Jun-Oct","draw_rank":1,"when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","hook":"Nyerere''s signature — a boat drifting the wide Rufiji past hippo pods, big crocodiles and extraordinary birdlife, with elephants at the shore","si":"adventure","blurb":"Nyerere''s signature — a boat drifting the wide Rufiji past hippo pods, big crocodiles and extraordinary birdlife, with elephants at the shore","when":"Jun-Oct","commission":"DMC/camp","wells":["activities"],"wells_basis":"derived from name/blurb/hook","si_all":["adventure","safari"],"shelf_fit":{"adventure":"primary","deepdive":"destination","romance":"destination","safari":"evidenced","ultra":"destination"},"commission_lane":["DMC"],"commission_embedded":false,"commission_basis":"lane"},{"name":"Walking safari + fly-camping","status":"live","tier":"premier","price_band":"~$70-500/pp","timing":"Jun-Oct","draw_rank":2,"when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","hook":"Only with the armed ranger/guide, single file, downwind discipline — big-predator, big-elephant country on foot; fly-camps follow strict camp rules","si":"adventure","blurb":"Only with the armed ranger/guide, single file, downwind discipline — big-predator, big-elephant country on foot; fly-camps follow strict camp rules","when":"Jun-Oct","commission":"DMC","wells":["stay","activities"],"wells_basis":"derived from name/blurb/hook","si_all":["adventure","safari"],"shelf_fit":{"adventure":"primary","deepdive":"destination","romance":"destination","safari":"evidenced","ultra":"destination"},"commission_lane":["DMC"],"commission_embedded":false,"commission_basis":"lane"},{"name":"UNESCO wilderness + wild-dog conservation","status":"future","tier":"premier","price_band":"on application","timing":"Jun-Oct","draw_rank":1,"when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","hook":"the UNESCO-listed Selous ecosystem and the Selous-Niassa wild-dog conservation story, plus the Rufiji''s ecology","si":"deepdive","blurb":"the UNESCO-listed Selous ecosystem and the Selous-Niassa wild-dog conservation story, plus the Rufiji''s ecology","when":"Jun-Oct","commission":"DMC/specialist","wells":[],"wells_basis":"text supports no Well — needs a human read","si_all":["deepdive"],"shelf_fit":{"adventure":"destination","deepdive":"primary","romance":"destination","safari":"destination","ultra":"destination"},"commission_lane":["DMC"],"commission_embedded":false,"commission_basis":"lane"},{"name":"A Sand Rivers / Siwandu honeymoon","status":"live","tier":"luxury","price_band":"~$900-2,500+/night all-in","timing":"standing; peak 4-8 mo","draw_rank":1,"hook":"Nomad''s Sand Rivers perched above the Rufiji, or Asilia''s Siwandu on a palm-fringed lake","si":"ultra","blurb":"Nomad''s Sand Rivers perched above the Rufiji, or Asilia''s Siwandu on a palm-fringed lake","when":"standing; peak 4-8 mo","commission":"consortia/Virtuoso + DMC","wells":[],"wells_basis":"text supports no Well — needs a human read","si_all":["romance","ultra"],"shelf_fit":{"adventure":"destination","deepdive":"destination","romance":"evidenced","safari":"destination","ultra":"primary"},"commission_lane":["DMC","consortia"],"commission_embedded":false,"commission_basis":"lane"},{"name":"A Rufiji riverside honeymoon","status":"live","tier":"luxury","price_band":"on application","timing":"Jun-Oct","draw_rank":1,"when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"romance","when":"Jun-Oct","commission":"consortia/host","wells":[],"wells_basis":"text supports no Well — needs a human read","si_all":["romance"],"shelf_fit":{"adventure":"destination","deepdive":"destination","romance":"primary","safari":"destination","ultra":"destination"},"commission_lane":["consortia"],"commission_embedded":false,"commission_basis":"lane"}],"faq":[{"q":"What''s the real risk to plan for at Nyerere?","a":"Not the northern Rufiji sector - the advisory''s concerns are the far-southern reaches toward the Mozambique border (terrorism, kept out of itineraries) and city petty crime, plus a flagged LGBTQ+ targeting concern travelers should weigh (Tanzanian law criminalizes same-sex relations). Practically: it''s a low-elevation river park, so malaria prophylaxis is essential, and keep back from hippos and crocs on the boat.","source":"newsweek.com","si_tag":"safety"},{"q":"What makes Nyerere different from a northern-circuit safari?","a":"The water. Alongside game drives and walking safaris, Nyerere''s signature is the Rufiji River boat safari - drifting past hippo pods, big crocodiles and extraordinary birdlife - an experience you can''t have in the Serengeti or Ngorongoro. Add one of Africa''s best wild-dog populations and near-empty wilderness, and it''s the standout of the southern circuit.","source":"nyererenationalpark.org","si_tag":"globaladv"},{"q":"When is the best time to visit Nyerere?","a":"The dry season, Jun-Oct, when game concentrates on the Rufiji and its lakes; the green season (Nov-Mar) is lush and excellent for birding, while the long rains (Apr-May) close some camps and soften the roads.","source":"expertafrica.com","si_tag":"safari"},{"q":"How do I get to Nyerere, and how long should I stay?","a":"By short fly-in from Dar (~45 min) or a 4-6-hour road transfer; give it 3-4 nights to combine boat safaris, game drives and a walking safari - ideally paired with Ruaha for a full southern-circuit week.","source":"expertafrica.com","si_tag":"safari"},{"q":"Do I need a visa or yellow-fever certificate for Tanzania?","a":"eVisa required - apply on the official portal before departure. Yellow fever is not required direct from the US/Europe, but is mandatory if you transit >12 h through a risk country like Kenya.","source":"tanzania-specialist.com","si_tag":"safety"}],"seo":{"meta_title":"Nyerere National Park (Selous) Guide: Rufiji Boat Safaris, Wild Dogs & Best Time","meta_description":"Plan a Nyerere/Selous safari - the largest national park in Africa: the Rufiji River boat safari, one of Africa''s best wild-dog populations, the Big Five and near-empty UNESCO wilderness - with the FCDO advisory, best time (Jun-Oct), the fly-in from Dar and where to stay on the southern circuit.","slug":"nyerere-selous-tanzania","primary_keyword":"Nyerere National Park Selous safari","long_tail":["Rufiji River boat safari","Selous wild dogs","Nyerere National Park boat safari","Selous vs Serengeti","is Tanzania safe safari","Nyerere best time to visit","southern circuit Tanzania"],"search_language":"sw","local_keywords":["Nyerere","Selous","Rufiji","mbwa mwitu","kiboko","mto"],"hreflang":["en","sw"],"jsonld_type":"TouristDestination","content_freshness":"2026-08-01","attribution":{"author":{"type":"Organization","name":"TravelWell.World"},"publisher":{"type":"Organization","name":"TravelWell.World LLC"},"reviewed_by":{"type":"Organization","name":"TravelWell.World"},"digital_source_type":"CompositeWithTrainedAlgorithmicMediaDigitalSource","digital_source_vocab":"https://schema.org/IPTCDigitalSourceEnumeration","last_verified":"2026-08-01","last_verified_basis":"source_verified","verified_against":[{"name":"UK Foreign, Commonwealth & Development Office","url":"https://www.gov.uk/foreign-travel-advice/tanzania","read":"2026-08-20T14:54:17Z","source_updated":"2026-05-19T15:47:49+01:00"}]}},"booking":{"codes":["reconsider-travel","mtwara-mozambique-border-carveout-far","lgbtq-targeting"],"book_suppressed":false,"note":"Nyerere''s photographic TOURIST sector is the northern Rufiji (near Dar), away from the park''s far-southern reaches toward the Mozambique border. also disclose the LGBTQ+ targeting consideration (same-sex relations criminalized). Travel with a licensed operator; keep to the northern Rufiji sector. Re-verify each cycle.","advisory_authority":"FCDO"},"si_checklist_25":{"run_date":"2026-08-01","hits":6,"misses":16,"disregarded":3,"note":"Canonical 25-SI list; per the safari-build rule big game/wild dogs is safari (PRIMARY here), NOT globaladv; the Rufiji boat safari + walking + fly-camping = globaladv; river (cruise) is a documented MISS - a safari boat, not a river-cruise ship; UNESCO/wild-dog conservation/Rufiji ecology = deepdive; sports limited to participant; spectator/prosports/compsports disregarded"},"sis_present":[{"si":"safari","name":"safari","status":"live","note":"big-game/wild dogs - a wild-dog stronghold + the Big Five (PRIMARY)"},{"si":"globaladv","name":"adventure","status":"live","note":"Rufiji River boat safari (signature) + walking safari + fly-camping"},{"si":"ultra","name":"ultra","status":"live","note":"Sand Rivers Selous / Siwandu"},{"si":"romance","name":"Romance, Marriages & Honeymoons","status":"live"},{"si":"deepdive","name":"deepdive","status":"future","note":"UNESCO / wild-dog conservation / Rufiji ecology"}],"ultra":[{"name":"Sand Rivers Selous (Nomad) / Siwandu (Asilia) - the riverside-luxury apex","why_ultra":"a stone lodge above the Rufiji and a lakeside tented camp, deep in Africa''s largest park, with private boat safaris and walking","earning":"consortia/Virtuoso","virtuoso_value_add":true,"mor":"commissionable-rack","tier":"ultra","price_band":"~$1,200-2,500+/night"},{"name":"A private boat-and-wild-dog week","why_ultra":"an exclusive-guide safari: Rufiji boat safaris + wild-dog tracking + walking + a fly-camp night, from an ultra camp","earning":"DMC/consortia","virtuoso_value_add":false,"mor":"commissionable","tier":"ultra","price_band":"on application"},{"name":"The private southern-circuit safari (Nyerere + Ruaha)","why_ultra":"Tanzania''s wild south flown and privately guided: Nyerere''s Rufiji boats + Ruaha''s great lion prides, far from the northern crowds","earning":"DMC/consortia","virtuoso_value_add":false,"mor":"commissionable","tier":"ultra","price_band":"on application"}],"source_verified":"2026-08-01","hero":{"query":"Nyerere National Park (Selous), Tanzania"},"geo":{"lat":-8,"lng":37.6},"orbit":[],"orbit_country":["lake-manyara-tanzania","ngorongoro-crater-tanzania","ruaha-tanzania","serengeti-tanzania","tarangire-tanzania"]}'::jsonb, 14),
  ('nyungwe-forest-rwanda', '05A', 'Nyungwe Forest National Park', 'Rwanda', 'An ancient cloud forest', 'live', 'verified', 'mountainValley', 'Rwanda — Nyungwe Forest', '{"adventure","ultra","romance","deepdive","culture"}', '{}', '{"essential","comfort","premier","luxury","ultra"}', null, 'core', '{"key_facts":["Rwanda''s ancient montane rainforest (~1,019 km2) on the Congo-Nile divide (Nile headwaters) - 13 primate species incl. 500+ chimpanzees and one of East Africa''s biggest colobus troops (up to ~400)","The chimp trek is the draw (globaladv-primary) - a strenuous 2-6h hike to a 1-hour habituated encounter, $250 permit (vs Rwanda''s $1,500 gorilla permit); safari (big-game) is a MISS - a forest, not a Big-Five park","East Africa''s FIRST canopy walkway (160m long, 70m high; $60); the Isumo waterfall hike (~10.6km, 4-5h, $15); 300+ birds incl. 29 Albertine-Rift endemics - a birder''s grail","disclose + consent","Best Jun-Sep + Dec-Feb (hiking/canopy, firmer trails); chimps often best Oct-May (fruiting); pairs into the 3-park Rwanda circuit with Volcanoes (gorillas) + Akagera (Big Five)","Sold via Rwandan safari DMCs 10-20% - IATAN/host-gated, CLIA has NO Africa representation; the $250 RDB chimp permit + canopy ($60)/waterfall ($15) fees are pass-through; RWF (~1,467/USD); visa on arrival $30; malaria present (lower at altitude); AMREF for evac"],"safety":{"emergency":"112 (police) / 912 ambulance / 111 fire; AMREF Flying Doctors for high-forest evac","hospital":"Remote/high forest - AMREF Flying Doctors (~$40 pp/30d) + travel-medical insurance; nearest referral Huye/Kigali","malaria":"present (chloroquine-resistant) - prophylaxis advised (lower at Nyungwe''s 1,600-2,950m but real); DEET","yellow_fever":"required only if arriving from a YF-endemic country (not direct from the US)","activity_note":"Chimp trek = strenuous 2-6h over steep/slippery montane slopes (good boots + fitness), rules 7-8m/mask/1hr/armed ranger. Canopy walkway sways 70m up (head-for-heights). Remote - carry AMREF evac + insurance","fcdo":{"posture":"AREA-RESTRICTED","quotes":[],"url":"https://www.gov.uk/foreign-travel-advice/rwanda","read":"2026-09-04T12:02:55Z","page_updated":"2026-09-04T10:15:14+01:00","source_country":"rwanda","quotes_note":"not extracted by the join — a restricted-area clause is quoted by a human, never composed"},"fcdo_zones":[{"name":"Within ~10 km of the DRC border","lvl":4,"except":["Volcanoes National Park"],"note":"Unrest. Multiple armed groups, individuals and military forces operate in North and South Kivu; violence may spill into Rwanda without warning. US government employees need special authorisation to travel here. State states Volcanoes National Park is not included in this area."}]},"timing":{"peak":"Jun-Sep + Dec-Feb (drier, firmer trails) for canopy walk/hiking/primates","shoulder":"Oct-Nov + Mar (softer rates; often better for chimps - fruiting)","green":"Apr-May (long rains - lush, muddiest, cheapest; chimps can be closer)","booking_lead":"lodges (very few) 2-5 mo for Jun-Sep + Dec-Feb; green 1-2 mo","off_season_specials":"the 3-park Rwanda circuit (Volcanoes + Nyungwe + Akagera) unlocks the Nov-May 30% gorilla-permit discount - sell Nyungwe as the forest/chimp leg; wet-season chimp + birding value","event_peaks":"Jun-Sep + Christmas/NY; birding season (migrants)","fire_date":"Jun-Sep hiking/canopy 4-6 mo out; 3-park circuit (with the gorilla discount) by prior Aug-Sep; position as the active affordable primate day beside the gorillas"},"jewels":[{"name":"Chimpanzee trekking","status":"live","tier":"premier","price_band":"~$250 permit + land","timing":"year-round; chimps best Oct-May","draw_rank":1,"hook":"A one-hour habituated-chimp encounter for a $250 permit — a strenuous, thrilling forest trek","si":"adventure","blurb":"A one-hour habituated-chimp encounter for a $250 permit — a strenuous, thrilling forest trek","when":"year-round; chimps best Oct-May","commission":"DMC/RDB","wells":["activities"],"wells_bas